import{_ as a}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as n,C as s,o as l,c as i,a2 as o,j as r,a as d,E as c}from"./chunks/framework.Dx-TCpNt.js";const P=JSON.parse('{"title":"切格工作台","description":"切格工作台是把一页变成结构化数据的地方。自动检测只是起点；工作台是为快速、可逆地修正检测结果而设计的。","frontmatter":{"description":"切格工作台是把一页变成结构化数据的地方。自动检测只是起点；工作台是为快速、可逆地修正检测结果而设计的。"},"headers":[],"relativePath":"zh/guide/panels.md","filePath":"zh/guide/panels.md","lastUpdated":1794725747000}'),h={name:"zh/guide/panels.md"};function g(b,t,p,m,u,f){const e=s("Badge");return l(),i("div",null,[t[6]||(t[6]=o('<h1 id="切格工作台" tabindex="-1">切格工作台 <a class="header-anchor" href="#切格工作台" aria-label="Permalink to &quot;切格工作台&quot;">​</a></h1><p>切格工作台是把一页变成结构化数据的地方。自动检测只是起点；工作台是为快速、可逆地修正检测结果而设计的。</p><figure class="shot"><img src="'+a+'" alt="切格工作台：检测出四个分格，带缩放手柄与标注工具栏"><figcaption>检测出的分格以带编号的方框画在底图上。选中的方框显示八个缩放手柄。标注工具栏位于分格工具下方。</figcaption></figure><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>后续每项功能都依赖分格：对照阅读、格级笔记、PNG 单格导出、HTML 导出。框错了，后面全错。自动检测能处理好大多数页面，但扉页、跨页、边缘窄条和非常规版式总需要人工介入。</p><h2 id="工具栏逐项说明" tabindex="-1">工具栏逐项说明 <a class="header-anchor" href="#工具栏逐项说明" aria-label="Permalink to &quot;工具栏逐项说明&quot;">​</a></h2><h3 id="第一行-——-底图与切分" tabindex="-1">第一行 —— 底图与切分 <a class="header-anchor" href="#第一行-——-底图与切分" aria-label="Permalink to &quot;第一行 —— 底图与切分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>控件</th><th>作用</th><th>说明</th></tr></thead><tbody><tr><td><strong>底图</strong>选择器</td><td>选择显示哪种语言的画面，并用它做检测。</td><td>分格矩形由本页所有语言共用，所以这里只改变你画框所依据的图。</td></tr><tr><td>检测器标签</td><td>显示生成当前分格的算法版本，例如 <code>xycut-1.3</code>、<code>layout:&lt;id&gt;</code>、<code>plugin:&lt;name&gt;</code>。</td><td><code>旧数据</code> 表示该页 JSON 早于版本记录功能。</td></tr><tr><td>状态文本</td><td>显示分格是<em>自动</em>、<em>按模板</em>、<em>按插件</em>还是<em>手动改过</em>，以及保存次数和最后一次编辑摘要。</td><td>这是编辑计数器，不是审计日志。</td></tr><tr><td><strong>自动切格</strong></td><td>在底图上运行检测，并替换当前分格。</td><td>检测进行中或本页没有图片时不可用。重新检测会丢弃手动修改。</td></tr><tr><td><strong>添加格子</strong></td><td>在页面中部附近添加一个默认分格。</td><td>更快的替代方式：双击空白处。</td></tr><tr><td><strong>合并 (n)</strong></td><td>把选中的分格合并为一个框，<code>source: &quot;merged&quot;</code>。</td><td>选中两个及以上分格时可用。</td></tr><tr><td><strong>删除</strong></td><td>删除选中的分格以及它们的格级笔记。</td><td>等同于 <code>Delete</code> / <code>Backspace</code>。</td></tr></tbody></table><h3 id="第一行-——-保存" tabindex="-1">第一行 —— 保存 <a class="header-anchor" href="#第一行-——-保存" aria-label="Permalink to &quot;第一行 —— 保存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>控件</th><th>作用</th></tr></thead><tbody><tr><td><strong>自动</strong></td><td>改动后约 0.7 秒自动保存。</td></tr><tr><td><strong>确认</strong></td><td>改动保持未保存，直到你点击 <strong>✓</strong> 或按 <code>Enter</code>。<strong>×</strong> 或 <code>Esc</code> 放弃并回到上次保存。</td></tr><tr><td><code>↶</code> / <code>↷</code></td><td>撤销 / 重做（<code>Ctrl+Z</code>、<code>Ctrl+Shift+Z</code>、<code>Ctrl+Y</code>）。</td></tr><tr><td><strong>✓</strong></td><td>保存当前页的改动（仅确认模式）。</td></tr><tr><td><strong>×</strong></td><td>放弃未保存的改动（仅确认模式）。</td></tr><tr><td><strong>未保存</strong>标记</td><td>确认模式下，页面有未保存改动时出现。</td></tr><tr><td><strong>编号</strong></td><td>显示或隐藏分格序号标记。</td></tr></tbody></table><p>保存模式会记在浏览器中。顶栏始终显示当前状态：<em>已保存</em>、<em>保存中…</em>、<em>待保存</em> 或 <em>未保存改动</em>。</p><h3 id="第一行-——-缩放" tabindex="-1">第一行 —— 缩放 <a class="header-anchor" href="#第一行-——-缩放" aria-label="Permalink to &quot;第一行 —— 缩放&quot;">​</a></h3><p><code>−</code> / 百分比 / <code>＋</code> 控件把舞台缩放从 50% 调到 300%，步进 15%。缩放只影响显示；分格坐标归一化到 <code>0..1</code>，不会改变。</p><h3 id="第二行-——-数值矩形" tabindex="-1">第二行 —— 数值矩形 <a class="header-anchor" href="#第二行-——-数值矩形" aria-label="Permalink to &quot;第二行 —— 数值矩形&quot;">​</a></h3><p>只选中一个分格时，第二行显示 <strong>格子坐标</strong>，含四个百分比输入框：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>X</code></td><td>左边缘，占页宽的百分比。</td></tr><tr><td><code>Y</code></td><td>上边缘，占页高的百分比。</td></tr><tr><td><code>W</code></td><td>宽度，占页宽的百分比。</td></tr><tr><td><code>H</code></td><td>高度，占页高的百分比。</td></tr></tbody></table><p>输入数值会立即更新分格。保存时，超出页面的数值会被限制回页面内。</p><h3 id="第二行-——-网格生成器" tabindex="-1">第二行 —— 网格生成器 <a class="header-anchor" href="#第二行-——-网格生成器" aria-label="Permalink to &quot;第二行 —— 网格生成器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>范围</th><th>含义</th></tr></thead><tbody><tr><td><strong>行</strong></td><td>1–8</td><td>行数。</td></tr><tr><td><strong>列</strong></td><td>1–6</td><td>列数。</td></tr><tr><td><strong>间距</strong></td><td>0–8 %</td><td>单元格之间的间隙，占页面的百分比。</td></tr><tr><td><strong>生成网格</strong></td><td>—</td><td>用均匀划分的网格替换当前分格。</td></tr></tbody></table><p>固定杂志版式的章节可以用网格；版式完全重复时，用<strong>分格模板</strong>。</p><h3 id="第二行-——-模板与-json" tabindex="-1">第二行 —— 模板与 JSON <a class="header-anchor" href="#第二行-——-模板与-json" aria-label="Permalink to &quot;第二行 —— 模板与 JSON&quot;">​</a></h3><p><strong>分格模板</strong> 会记录当前页的矩形：</p><ol><li>打开 <strong>分格模板</strong>，输入名称，点击 <strong>把当前页存为模板</strong>。</li><li>选择模板，然后 <strong>套用本页</strong> 或 <strong>套用整话</strong>。</li><li>套用到整话时会要求确认，因为已有分格会被覆盖。</li></ol><p>新页面的分格数与模板相同时，格级笔记会按阅读顺序重新映射。数量不同时，格级笔记会被丢弃，而不是悄悄挂到错误的分格上；整页笔记始终保留。模板保存在 <code>data/templates/panel.json</code>。</p><p><strong>复制 JSON 路径</strong> 复制 <code>data/pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</code>。支持手工编辑该文件；服务器在读取时会规范化矩形、修复缺失的 id，并丢弃悬空引用。</p><h2 id="画布上的鼠标与键盘" tabindex="-1">画布上的鼠标与键盘 <a class="header-anchor" href="#画布上的鼠标与键盘" aria-label="Permalink to &quot;画布上的鼠标与键盘&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>手势</th></tr></thead><tbody><tr><td>移动分格</td><td>拖动框体。</td></tr><tr><td>缩放</td><td>拖动八个手柄之一。</td></tr><tr><td>快速添加分格</td><td>双击空白处。</td></tr><tr><td>精确框选分格</td><td>在空白处拖拽。</td></tr><tr><td>约束为正方形</td><td>拖拽时按住 <code>Shift</code>。</td></tr><tr><td>关闭吸附</td><td>拖拽或绘制时按住 <code>Alt</code>。</td></tr><tr><td>取消当前框</td><td><code>Esc</code>。</td></tr><tr><td>多选</td><td><code>Ctrl</code> 点击或 <code>Shift</code> 点击方框。</td></tr><tr><td>微调</td><td>方向键移动选中项 0.2%；<code>Shift</code> + 方向键移动 1%。</td></tr><tr><td>删除</td><td><code>Delete</code> 或 <code>Backspace</code>。</td></tr><tr><td>保存 / 放弃（确认模式）</td><td><code>Enter</code> / <code>Esc</code>。</td></tr></tbody></table><p>所有坐标都以页面为基准归一化，因此分格在任何缩放级别或导出分辨率下位置都不变。</p><h2 id="编号与阅读方向" tabindex="-1">编号与阅读方向 <a class="header-anchor" href="#编号与阅读方向" aria-label="Permalink to &quot;编号与阅读方向&quot;">​</a></h2><ul><li><strong>编号</strong> 切换序号标记。</li><li>阅读方向按页面存储：<code>rtl</code>（从右到左 · 从上到下）、<code>ltr</code>（从左到右 · 从上到下）或 <code>ttb</code>（从右到左 · 竖排）。在顶栏修改。</li><li>分格可以带显式的 <code>number</code>，覆盖自动阅读顺序；否则编号由矩形和阅读方向推导。</li><li>同一顺序也驱动对照阅读、笔记总览和 HTML 导出。</li></ul><div class="tip custom-block"><p class="custom-block-title">先定阅读顺序</p><p>开始编辑前如果分格编号看起来不对，先改阅读方向选择器。可以在 JSON 里手工重新编号，但修改方向会一次性修正整话的所有页面。</p></div><h2 id="标注工具" tabindex="-1">标注工具 <a class="header-anchor" href="#标注工具" aria-label="Permalink to &quot;标注工具&quot;">​</a></h2><p>标注图层画在画面之上，与分格分开存储。</p><table tabindex="0"><thead><tr><th>控件</th><th>作用</th></tr></thead><tbody><tr><td><strong>标注：显示中 / 已隐藏</strong></td><td>全局可见性。隐藏会保留数据，并在导出中隐藏。</td></tr><tr><td><strong>选择与移动</strong></td><td>选中已有标注；拖动可移动。</td></tr><tr><td><strong>箭头</strong></td><td>从尾部拖到头部。</td></tr><tr><td><strong>矩形</strong> / <strong>椭圆</strong></td><td>拖出方框或椭圆。</td></tr><tr><td><strong>荧光笔</strong></td><td>半透明自由笔迹。</td></tr><tr><td><strong>自由笔迹</strong></td><td>不透明笔迹；保留完整折线。</td></tr><tr><td><strong>文字</strong></td><td>点击后输入文字。</td></tr><tr><td><strong>编号圆标</strong></td><td>点击后输入编号。</td></tr><tr><td><strong>马赛克</strong></td><td>拖出矩形；该区域被像素化。</td></tr><tr><td><strong>颜色样块</strong></td><td>设置新标注的颜色；选中标注时点击样块可为它改色。</td></tr><tr><td><strong>删除</strong></td><td>删除选中的标注。</td></tr><tr><td><strong>清空</strong></td><td>确认后删除本页所有标注。</td></tr></tbody></table><p>作用范围跟随选择：选中一个分格时，提示为<em>新标注画在格 N 内</em>；没有选中时，<em>新标注作用于整页</em>。<code>Esc</code> 退出当前工具或取消选中标注。</p><p>只有标注图层显示时，导出的 HTML 和 PNG 才包含标注。HTML 导出还有一个 <strong>在原图上标出格子边框</strong> 选项，它与标注无关。</p><h2 id="分组" tabindex="-1">分组 <a class="header-anchor" href="#分组" aria-label="Permalink to &quot;分组&quot;">​</a></h2>',37)),r("p",null,[t[0]||(t[0]=d("页面 JSON 有一个 ",-1)),t[1]||(t[1]=r("code",null,"groups",-1)),t[2]||(t[2]=d(" 字段（",-1)),t[3]||(t[3]=r("code",null,"{ id, name, panelIds, number }",-1)),t[4]||(t[4]=d("），读取、写入、导入和导出时都会保留。",-1)),c(e,{type:"warning",text:"计划中"}),t[5]||(t[5]=d(" 目前应用内没有创建或编辑分组的界面，只有直接编辑 JSON 才能改动它们。",-1))]),t[7]||(t[7]=o('<h2 id="安全的修正流程" tabindex="-1">安全的修正流程 <a class="header-anchor" href="#安全的修正流程" aria-label="Permalink to &quot;安全的修正流程&quot;">​</a></h2><ol><li>打开页面，让自动检测运行。</li><li>修正明显的框：移动、缩放、添加、删除。</li><li>合并跨页大图的分格。</li><li>保存（确认模式下按 <code>✓</code>）。</li><li>切换到 <strong>对照阅读</strong>（<code>C</code>），确认同一个分格确实包含同一块画面。</li></ol><p>手动改过之后，除非愿意丢失修改，否则不要再运行 <strong>自动切格</strong>。</p><figure class="shot"><div class="shot-missing"><strong>截图待补：分格工具栏特写</strong> 两行工具栏和标注工具栏的裁剪截图将补在这里。 </div><figcaption>计划中的截图：带编号标注的工具栏控件。</figcaption></figure><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>自动切格替换了我的框。</strong> 检测会覆盖。第一次切分成功后，改用分格模板或手工编辑。</li><li><strong>页面没有图片。</strong> 检测被禁用，舞台显示空状态。补上缺失的语言文件夹，或在卷设置里映射。</li><li><strong>WebP 页面检测不了。</strong> WebP 可以显示，但不会解码用于检测；请转成 JPEG 或 PNG。</li><li><strong>套用模板后格级笔记不见了。</strong> 模板的分格数不同，格级笔记被丢弃；整页笔记保留。需要时从备份恢复。</li><li><strong>“未保存改动”一直不消失。</strong> 你处于确认模式。按 <code>✓</code> 或 <code>Enter</code>；<code>×</code> 放弃。</li><li><strong>标注看不见。</strong> 标注图层被隐藏，或分格筛选处于激活状态。检查 <strong>标注：显示中</strong>。</li></ul><h2 id="缺失的截图" tabindex="-1">缺失的截图 <a class="header-anchor" href="#缺失的截图" aria-label="Permalink to &quot;缺失的截图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图</th><th>用于</th></tr></thead><tbody><tr><td>工具栏特写</td><td>第一行与第二行控件</td></tr><tr><td>标注工具栏特写</td><td>工具图标与颜色样块</td></tr><tr><td>分格模板面板</td><td>模板保存 / 套用控件</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/compare">对照阅读</a> —— 分格是用来做什么的。</li><li><a href="/KomaYomi-docs/zh/data-format">数据格式</a> —— 页面 JSON 的约定。</li><li><a href="/KomaYomi-docs/zh/guide/shortcuts">键盘快捷键</a> —— 所有按键集中在一张表里。</li></ul>',10))])}const _=n(h,[["render",g]]);export{P as __pageData,_ as default};
